std_ticket_config_action.applicability_script:
(function() {
    var userId = gs.getUserID();
    var userName = gs.getUserName();
    var groupId = current.getValue('assignment_group');

    // 1. Check if state is "En edición" (1)
    if (current.state == 8) { 

        // Admin override
        if (gs.hasRole('admin')) {
            gs.info('Action Applicability: User {0} is Admin. Access granted.', userName);
            return true;
        }

        // 2. Validate Assignment Group membership
        if (groupId) {
            var isMember = gs.getUser().isMemberOf(groupId);

            // Logging the result for debugging
            gs.info('Action Applicability: User {0} checking membership for Group {1}. Result: {2}', [userName, groupId, isMember]);

            if (isMember) {
                return true;
            }
        } else {
            gs.warn('Action Applicability: Assignment Group is empty for record {0}.', current.getDisplayValue());
        }
    }

    return false;
})();
